+package com.example.contact;
+
+import java.util.List;
+import java.util.concurrent.CopyOnWriteArrayList;
+
+import org.springframework.stereotype.Service;
+
+/**
+ * Keeps messages for the lifetime of the application.  It is deliberately not
+ * backed by a database: messages should survive navigation, but not restarts.
+ */
+@Service
+public class ContactMessageService {
+    private final List<ContactMessage> messages = new CopyOnWriteArrayList<>();
+
+    public void add(ContactMessage message) {
+        messages.add(0, message);
+    }
+
+    public List<ContactMessage> findAll() {
+        return List.copyOf(messages);
+    }
+}
