+package com.example.contact;
+
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.html.Span;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.orderedlayout.HorizontalLayout;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+
+@Route("contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+    private final ContactMessageService messageService;
+
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final Button send = new Button("Send");
+    private final Grid<ContactMessage> messages = new Grid<>(ContactMessage.class, false);
+
+    public ContactView(ContactMessageService messageService) {
+        this.messageService = messageService;
+
+        add(new H1("Contact"));
+        add(new RouterLink("About", AboutView.class));
+
+        add(name, email, phone, message, send);
+
+        messages.addColumn(ContactMessage::name).setHeader("Name");
+        messages.addColumn(ContactMessage::message).setHeader("Message");
+        refreshMessages();
+        add(messages);
+
+        send.addClickListener(event -> sendMessage());
+        send.addClickShortcut(Key.ENTER);
+
+        name.addValueChangeListener(event -> enableAfterEdit());
+        email.addValueChangeListener(event -> enableAfterEdit());
+        phone.addValueChangeListener(event -> enableAfterEdit());
+        message.addValueChangeListener(event -> enableAfterEdit());
+    }
+
+    private void enableAfterEdit() {
+        // This is only disabled immediately after a successful submission.
+        if (!send.isEnabled()) {
+            send.setEnabled(true);
+        }
+    }
+
+    private void sendMessage() {
+        if (!isValid()) {
+            return;
+        }
+
+        messageService.add(new ContactMessage(
+                name.getValue(), email.getValue(), phone.getValue(), message.getValue()));
+        refreshMessages();
+        name.clear();
+        email.clear();
+        phone.clear();
+        message.clear();
+        // Clearing fields can fire value-change events; set this last.
+        send.setEnabled(false);
+        Notification.show("Message sent");
+    }
+
+    private boolean isValid() {
+        clearValidation();
+        boolean valid = true;
+
+        if (name.getValue().isBlank()) {
+            markInvalid(name, "Name is required");
+            valid = false;
+        }
+
+        String emailAddress = email.getValue();
+        if (!emailAddress.isEmpty() && !isEmailAddress(emailAddress)) {
+            markInvalid(email, "Enter a valid e-mail address");
+            valid = false;
+        } else if (emailAddress.isEmpty() && phone.getValue().isBlank()) {
+            markInvalid(email, "Give an e-mail address or a phone number");
+            valid = false;
+        }
+
+        if (message.getValue().isBlank()) {
+            markInvalid(message, "Message is required");
+            valid = false;
+        } else if (message.getValue().length() > 500) {
+            markInvalid(message, "Message must be at most 500 characters");
+            valid = false;
+        }
+        return valid;
+    }
+
+    private boolean isEmailAddress(String value) {
+        return value.matches("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
+    }
+
+    private void clearValidation() {
+        name.setErrorMessage(null);
+        name.setInvalid(false);
+        email.setErrorMessage(null);
+        email.setInvalid(false);
+        phone.setErrorMessage(null);
+        phone.setInvalid(false);
+        message.setErrorMessage(null);
+        message.setInvalid(false);
+    }
+
+    private void markInvalid(TextField field, String errorMessage) {
+        field.setErrorMessage(errorMessage);
+        field.setInvalid(true);
+    }
+
+    private void markInvalid(EmailField field, String errorMessage) {
+        field.setErrorMessage(errorMessage);
+        field.setInvalid(true);
+    }
+
+    private void markInvalid(TextArea field, String errorMessage) {
+        field.setErrorMessage(errorMessage);
+        field.setInvalid(true);
+    }
+
+    private void refreshMessages() {
+        messages.setItems(messageService.findAll());
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (!hasUnsavedInput()) {
+            return;
+        }
+
+        BeforeLeaveEvent.ContinueNavigationAction navigation = event.postpone();
+        Dialog dialog = new Dialog();
+        Button keepEditing = new Button("Keep editing", click -> dialog.close());
+        Button discard = new Button("Discard", click -> {
+            dialog.close();
+            navigation.proceed();
+        });
+        dialog.add(new Span("Discard the message you are editing?"), new HorizontalLayout(keepEditing, discard));
+        dialog.open();
+    }
+
+    private boolean hasUnsavedInput() {
+        return !name.getValue().isEmpty()
+                || !email.getValue().isEmpty()
+                || !phone.getValue().isEmpty()
+                || !message.getValue().isEmpty();
+    }
+}
